package ro.leo.visual;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.telecom.TelecomManager;import java.io.*;import java.util.*;import org.json.*;
/** Two sequential package sessions, with a durable journal and one previous APK pair. */
final class UpdateEngine {
 static final String CHANGED="ro.leo.visual.UPDATE_CHANGED";static final String[] PACKAGES={"ro.leo.keypad","ro.leo.visual"};
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("app-updates",0);}
 static File base(Context c){File f=new File(c.getFilesDir(),"updates");f.mkdirs();return f;}
 static File folder(Context c,String key)throws IOException{String name=prefs(c).getString(key,"");if(!name.matches("(stage|previous)-[A-Za-z0-9-]+"))throw new IOException("Pachet lipsă");File f=new File(base(c),name);if(!f.isDirectory())throw new IOException("Copie lipsă");return f;}
 static Set<String> signatures(PackageInfo p)throws Exception{if(p.signatures==null||p.signatures.length==0)throw new IOException("Certificat lipsă");Set<String> out=new HashSet<String>();for(Signature s:p.signatures)out.add(BackupEngine.hash(s.toByteArray()));return out;}
 static PackageInfo validate(Context c,File file,int index)throws Exception{PackageManager pm=c.getPackageManager();PackageInfo apk=pm.getPackageArchiveInfo(file.getPath(),PackageManager.GET_SIGNATURES),installed=pm.getPackageInfo(PACKAGES[index],PackageManager.GET_SIGNATURES);if(apk==null||!PACKAGES[index].equals(apk.packageName)||!signatures(apk).equals(signatures(installed)))throw new IOException("Pachet sau semnătură incompatibilă");if(installed.applicationInfo.splitSourceDirs!=null&&installed.applicationInfo.splitSourceDirs.length>0)throw new IOException("Pachetele split nu sunt acceptate");return apk;}
 static synchronized String stage(Context c,File zip)throws Exception{if(prefs(c).getBoolean("active",false))throw new IOException("Încheie întâi actualizarea în curs");if(!ReaderActivity.allowed(c,zip))throw new IOException("Alege o arhivă din memoria telefonului / SD");File dir=new File(base(c),"stage-"+UUID.randomUUID());if(!dir.mkdir())throw new IOException();try{JSONObject manifest=AppBundle.unpack(zip,dir);for(int n=0;n<2;n++){PackageInfo apk=validate(c,new File(dir,AppBundle.FILES[n]),n);if(apk.versionCode!=manifest.getInt("version_code")||!manifest.getString("version").equals(apk.versionName))throw new IOException("Versiuni nealiniate");}if(!prefs(c).edit().putString("stage",dir.getName()).putString("version",manifest.getString("version")).putString("message","Pachet verificat · "+manifest.getString("version")).commit())throw new IOException();clean(c);return manifest.getString("version");}catch(Exception e){delete(dir);throw e;}}
 static void copy(File from,File to)throws Exception{try(InputStream in=new FileInputStream(from);FileOutputStream out=new FileOutputStream(to)){byte[] b=new byte[65536];int n;long count=0;while((n=in.read(b))!=-1){count+=n;if(count>33554432)throw new IOException();out.write(b,0,n);}out.getFD().sync();}if(!AppBundle.digest(from).equals(AppBundle.digest(to)))throw new IOException("Copie APK neverificată");}
 static void snapshot(Context c,String identity)throws Exception{File dir=new File(base(c),"previous-"+UUID.randomUUID());if(!dir.mkdir())throw new IOException();try{JSONObject hashes=new JSONObject();StringBuilder versions=new StringBuilder();for(int n=0;n<2;n++){PackageInfo installed=c.getPackageManager().getPackageInfo(PACKAGES[n],0);ApplicationInfo app=installed.applicationInfo;if(app.splitSourceDirs!=null&&app.splitSourceDirs.length>0)throw new IOException();File target=new File(dir,AppBundle.FILES[n]);copy(new File(app.sourceDir),target);hashes.put(AppBundle.FILES[n],AppBundle.digest(target));if(n>0)versions.append(" / ");versions.append(installed.versionName==null?"cod "+installed.versionCode:installed.versionName);}BackupEngine.write(new File(dir,"hashes.json"),hashes.toString().getBytes("UTF-8"));if(!prefs(c).edit().putString("previous",dir.getName()).putString("previous-label",versions.toString()).putString("checkpoint-target",identity).commit())throw new IOException();}catch(Exception e){delete(dir);throw e;}}
 static synchronized void begin(Context c,boolean rollback)throws Exception{if(prefs(c).getBoolean("active",false))throw new IOException("O instalare este deja în curs");if(!c.getPackageManager().canRequestPackageInstalls())throw new IOException("Permite întâi instalările din Leo");TelecomManager telecom=(TelecomManager)c.getSystemService(Context.TELECOM_SERVICE);if(telecom!=null&&telecom.isInCall())throw new IOException("Închide apelul înainte de actualizare");File dir=folder(c,rollback?"previous":"stage");for(int n=0;n<2;n++)validate(c,new File(dir,AppBundle.FILES[n]),n);if(!rollback){JSONObject manifest=new JSONObject(new String(BackupEngine.bytes(new File(dir,"manifest.json"),262144),"UTF-8"));JSONObject files=manifest.getJSONObject("files");String identity=files.getJSONObject(AppBundle.FILES[0]).getString("sha256")+files.getJSONObject(AppBundle.FILES[1]).getString("sha256");boolean have=true;try{File previous=folder(c,"previous");have=new File(previous,"hashes.json").isFile()&&new File(previous,AppBundle.FILES[0]).isFile()&&new File(previous,AppBundle.FILES[1]).isFile();}catch(IOException absent){have=false;}if(!have||!identity.equals(prefs(c).getString("checkpoint-target","")))snapshot(c,identity);}if(!prefs(c).edit().putBoolean("active",true).putBoolean("rollback",rollback).putInt("step",0).putInt("session",-1).putString("token",UUID.randomUUID().toString()).putString("message",rollback?"Revenire pregătită":"Actualizare pregătită").commit())throw new IOException();c.startForegroundService(new Intent(c,UpdateService.class));}
 static synchronized void run(Context c)throws Exception{SharedPreferences p=prefs(c);if(!p.getBoolean("active",false)||p.getInt("session",-1)>=0)return;int step=p.getInt("step",0);if(step>=2)return;TelecomManager t=(TelecomManager)c.getSystemService(Context.TELECOM_SERVICE);if(t!=null&&t.isInCall())throw new IOException("Instalare oprită: apel activ");boolean rollback=p.getBoolean("rollback",false);File dir=folder(c,rollback?"previous":"stage"),apk=new File(dir,AppBundle.FILES[step]);validate(c,apk,step);
  if(rollback){JSONObject hashes=new JSONObject(new String(BackupEngine.bytes(new File(dir,"hashes.json"),16384),"UTF-8"));if(!AppBundle.digest(apk).equals(hashes.getString(AppBundle.FILES[step])))throw new IOException("Copia precedentă a fost modificată");}else{JSONObject manifest=new JSONObject(new String(BackupEngine.bytes(new File(dir,"manifest.json"),262144),"UTF-8"));if(!AppBundle.digest(apk).equals(manifest.getJSONObject("files").getJSONObject(AppBundle.FILES[step]).getString("sha256")))throw new IOException("APK modificat după verificare");}
  PackageInstaller installer=c.getPackageManager().getPackageInstaller();PackageInstaller.SessionParams params=new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL);params.setAppPackageName(PACKAGES[step]);params.setSize(apk.length());if(rollback){String debug=(String)Class.forName("android.os.SystemProperties").getMethod("get",String.class,String.class).invoke(null,"ro.debuggable","0");PackageInfo current=c.getPackageManager().getPackageInfo(PACKAGES[step],0),old=c.getPackageManager().getPackageArchiveInfo(apk.getPath(),0);if(old.versionCode<current.versionCode&&!debug.equals("1"))throw new IOException("Android poate reveni la o versiune mai veche numai pe build debuggable");java.lang.reflect.Field flags=PackageInstaller.SessionParams.class.getDeclaredField("installFlags");flags.setAccessible(true);flags.setInt(params,flags.getInt(params)|128);}
  int id=installer.createSession(params);boolean committed=false;try(PackageInstaller.Session session=installer.openSession(id);InputStream in=new FileInputStream(apk)){try(OutputStream out=session.openWrite("base.apk",0,apk.length())){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);session.fsync(out);}if(!p.edit().putInt("session",id).putString("message","Instalare "+PACKAGES[step]+" · aștept confirmarea Android").commit())throw new IOException();Intent result=new Intent(c,UpdateResultReceiver.class).setData(Uri.parse("leo-update://session/"+id)).putExtra("token",p.getString("token",""));PendingIntent pending=PendingIntent.getBroadcast(c,id,result,PendingIntent.FLAG_UPDATE_CURRENT);session.commit(pending.getIntentSender());committed=true;}finally{if(!committed)installer.abandonSession(id);}
 }
 static synchronized void result(Context c,Intent result){SharedPreferences p=prefs(c);if(!p.getBoolean("active",false)||!p.getString("token","").equals(result.getStringExtra("token"))||p.getInt("session",-2)!=result.getIntExtra(PackageInstaller.EXTRA_SESSION_ID,-1))return;int status=result.getIntExtra(PackageInstaller.EXTRA_STATUS,PackageInstaller.STATUS_FAILURE);if(status==PackageInstaller.STATUS_PENDING_USER_ACTION){Intent confirm=result.getParcelableExtra(Intent.EXTRA_INTENT);if(confirm!=null)try{c.startActivity(confirm.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(RuntimeException e){fail(c,"Confirmarea Android nu poate fi deschisă");}}else if(status==PackageInstaller.STATUS_SUCCESS)advance(c);else fail(c,"Instalare nereușită · cod "+status);changed(c);}
 static synchronized void advance(Context c){SharedPreferences p=prefs(c);int step=p.getInt("step",0)+1;boolean finished=step>=2;p.edit().putInt("step",step).putInt("session",-1).putBoolean("active",!finished).putString("message",finished?"Ambele APK-uri instalate · redeschide Leo":"Primul APK instalat · urmează Leo Visual").commit();if(!finished)c.startForegroundService(new Intent(c,UpdateService.class));else clean(c);}
 static synchronized void reconcile(Context c)throws Exception{SharedPreferences p=prefs(c);int id=p.getInt("session",-1);if(!p.getBoolean("active",false)||id<0)return;if(c.getPackageManager().getPackageInstaller().getSessionInfo(id)!=null)return;int step=p.getInt("step",0);if(step>1)return;File dir=folder(c,p.getBoolean("rollback",false)?"previous":"stage");String installed=c.getPackageManager().getApplicationInfo(PACKAGES[step],0).sourceDir;if(AppBundle.digest(new File(installed)).equals(AppBundle.digest(new File(dir,AppBundle.FILES[step]))))advance(c);else fail(c,"Sesiunea nu mai există · verifică sau reîncearcă pachetul");}
 static synchronized void cancel(Context c){SharedPreferences p=prefs(c);int id=p.getInt("session",-1);if(id>=0)try{c.getPackageManager().getPackageInstaller().abandonSession(id);}catch(RuntimeException e){p.edit().putString("message","Sesiune deja confirmată · folosește fereastra Android").apply();changed(c);return;}fail(c,"Instalare anulată · APK-urile deja aplicate rămân; copia precedentă este păstrată");}
 static synchronized void fail(Context c,String message){prefs(c).edit().putBoolean("active",false).putInt("session",-1).putString("message",message).commit();changed(c);}
 static void changed(Context c){c.sendBroadcast(new Intent(CHANGED).setPackage(c.getPackageName()));}
 static void delete(File dir){File[] files=dir.listFiles();if(files!=null)for(File f:files)if(f.isFile())f.delete();dir.delete();}
 static synchronized void clean(Context c){File[] dirs=base(c).listFiles();if(dirs==null)return;String stage=prefs(c).getString("stage",""),previous=prefs(c).getString("previous","");for(File f:dirs)if(f.isDirectory()&&f.getName().matches("(stage|previous)-[A-Za-z0-9-]+")&&!f.getName().equals(stage)&&!f.getName().equals(previous))delete(f);}
}
